// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(address attacker, uint256 value) public {
        vm.assume(attacker != address(0));
        vm.assume(attacker != c.Owner());
        value = bound(value, 0, address(this).balance);
        vm.deal(attacker, value);
        vm.prank(attacker);
        bool okRef;
        try c.Command{value: value}(address(0), "") { okRef = true; } catch { okRef = false; }
        assertTrue(!okRef);
    }
}
